def S(ad, sure, hedef, onsart, oku, ezber, uygulama, olcut):
    return dict(ad=ad, sure=sure, hedef=hedef, onsart=onsart, oku=[dict(k=k, n=n) for k, n in oku], ezber=ezber, uygulama=uygulama, olcut=olcut)
def A(baslik, soru, kaynak, ipucu, cevap):
    return dict(b=baslik, s=soru, k=kaynak, i=ipucu, c=cevap)

