ALISTIRMA['hadis'] = [
 A('Niyet hadisinin senedi', '“İnneme’l-a‘mâlü bi’n-niyyât” hadisi Kütüb-i Sitte’de yaygın olduğu hâlde neden “garîb” sayılır?', 'Buhârî, Bed’ü’l-vahy 1; Nüzhetü’n-nazar (garîb bahsi); Fethu’l-bârî', 'İlk dört halkadaki râvileri say.',
   'Hadisi Hz. Peygamber’den yalnız Hz. Ömer, ondan yalnız Alkame b. Vakkâs, ondan yalnız Muhammed b. İbrâhîm et-Teymî, ondan yalnız Yahyâ b. Saîd el-Ensârî rivayet eder. Yahyâ’dan sonra çok sayıda râvi nakletmiştir. Bu yüzden başında “ferd-i mutlak” (garîb), sonunda meşhurdur; garîb olması sahihliğine engel değildir.'),
 A('“İlim Çin’de de olsa…”', '“Çin’de de olsa ilim isteyin” sözünün hadis olarak durumu nedir?', 'Sehâvî, el-Makāsıdü’l-hasene; Aclûnî, Keşfü’l-hafâ', 'Sehâvî’nin eserinde maddeler alfabetiktir: “utlubû” ile ara.',
   'Söz Beyhakī ve İbn Adî gibi kaynaklarda zayıf senetlerle geçer. İbn Hibbân ve başka muhaddisler “bâtıl” demiş, Sehâvî zayıf olduğunu belirtmiştir. İkinci kısmı “ilim istemek her Müslümana farzdır” ise başka yollardan gelir ve bazı âlimlerce hasen kabul edilir.'),
 A('“Vatan sevgisi imandandır”', 'Bu söz bir hadis midir?', 'Sehâvî, el-Makāsıdü’l-hasene; Aliyyü’l-Kārî, el-Esrârü’l-merfûa', '“Lem akif aleyh” ifadesinin anlamını bil.',
   'Sehâvî “Bunu (bir senetle) bulamadım (lem akif aleyh)” der; anlamının doğru olduğunu ekler. Aliyyü’l-Kārî de hadis olarak asılsız sayar. Yani söz hadis değildir; ancak anlamı bazı hadislerle desteklenebilir.'),
 A('Bir râvinin derecesi', 'Abdullah b. Lehîa’nın rivayetleri nasıl değerlendirilir?', 'İbn Hacer, Takrîbü’t-tehzîb; Zehebî, Mîzânü’l-i‘tidâl', 'Kitaplarının başına gelen olayı ara.',
   'İbn Hacer Takrîb’de onu “sadûk” sayar ve kitapları yandıktan sonra karıştırdığını belirtir. Bu yüzden kitapları yanmadan önce ondan rivayet edenlerin (Abdullah b. Mübârek, Abdullah b. Vehb gibi) rivayetleri daha güçlü kabul edilir.'),
 A('Hastalık bulaşır mı?', '“Lâ adve” (hastalık bulaşmaz) hadisi ile “Cüzzamlıdan aslandan kaçar gibi kaç” hadisi nasıl uzlaştırılır?', 'Buhârî, Tıb 19 ve 53; Fethu’l-bârî; Nevevî, Müslim şerhi, Selâm bölümü', 'Bu bir muhtelifü’l-hadîs örneğidir; “cem‘” yollarını ara.',
   'İki hadis de Buhârî’dedir. Uzlaştırma yollarından biri: “Lâ adve” hastalığın kendi başına, Allah’ın takdiri olmadan bulaşmadığını (Câhiliye inancının reddi), kaçınma emri ise sebeplere riayeti öğretir. Başka âlimler kaçınma emrini zayıf imanlıların kalbini korumaya yorumlar. İbn Hacer bu görüşleri sıralar.'),
 A('Mürsel hadisin değeri', 'Saîd b. el-Müseyyeb’in mürselleri neden ayrı bir değer taşır?', 'Nüzhetü’n-nazar (mürsel); İbnü’s-Salâh, Mukaddime; Şâfiî, er-Risâle', 'Şâfiî’nin mürseli kabul şartlarını hatırla.',
   'Hanefî ve Mâlikîler güvenilir tâbiînin mürselini genel olarak kabul eder. Şâfiî ise ancak bir destekle (başka bir senet, sahâbe sözü veya ilim ehlinin amel etmesi) kabul eder, fakat Saîd b. el-Müseyyeb’in mürsellerini araştırıp çoğunun muttasıl bulunduğunu söylediği için ayrıca değerli görür.'),
 A('Buhârî’nin bab başlıkları', 'Buhârî’nin bab başlıklarına (terâcim) neden “Buhârî’nin fıkhı onun terâcimindedir” denir?', 'Fethu’l-bârî ve Hedyü’s-sârî (terâcim bahsi); Şah Veliyyullah, Şerhu terâcimi ebvâbi’l-Buhârî', 'Bir bab başlığının hadisle doğrudan ilgisi görünmediği bir örnek bul.',
   'Buhârî, babın başlığına kendi fıkhî kanaatini koyar; bazen başlığı bir âyet, sahâbe sözü veya hadisten çıkardığı bir hükümle yazar ve altına bu hükme dolaylı olarak delâlet eden hadisi koyar. Şârihler bu bağı kurmaya çalışır; bu yüzden terâcim Buhârî’nin fıkıh anlayışını gösterir.')]

