ALISTIRMA['akaid'] = [
 A('İman artar mı?', 'İman artar ve eksilir mi? Ekoller bu soruya neden farklı cevap verir?', 'el-Fıkhu’l-ekber; Tahâviyye (“el-îmânu vâhid”); Şerhu’l-Akāid; Buhârî, Îmân 1 (bab başlığı)', 'Önce imanın tarifinde amelin yerini bul.',
   'Hanefî-Mâtürîdîlere göre iman kalp ile tasdik (ve dil ile ikrar) olduğundan özü artmaz ve eksilmez; ameller imanın parçası değildir. Muhaddisler ve Eş‘arîlerin çoğuna göre amel imanın kemaline dahildir, bu yüzden iman artar ve eksilir; Buhârî de bab başlığında bunu söyler. Teftâzânî ihtilafın büyük ölçüde lafzî olduğunu, tasdikin kuvvet ve zaafının kabul edildiğini belirtir.'),
 A('Büyük günah işleyenin durumu', 'Büyük günah işleyen Müslümanın durumu hakkında Hâricîler, Mu‘tezile ve Ehl-i sünnet ne der?', 'el-Fark beyne’l-fırak; el-Milel ve’n-nihal; Şerhu’l-Akāid', 'Vâsıl b. Atâ’nın Hasan-ı Basrî’den ayrılış kıssasını hatırla.',
   'Hâricîler kâfir olduğunu söyler. Mu‘tezile’ye göre ne mü’min ne kâfirdir, “iki konum arasında bir konum”dadır; tövbesiz ölürse ebedî cehennemliktir. Ehl-i sünnete göre mü’mindir ama günahkârdır (fâsık); durumu Allah’ın dilemesine kalmıştır, affedilebilir veya cezalandırıldıktan sonra cennete girer.'),
 A('Tekvin sıfatı', 'Tekvin (yaratma) sıfatı ezelî bir sıfat mıdır?', 'Nesefî Akaidi ve Şerhu’l-Akāid; Tebsıratü’l-edille; Kemalpaşazâde’nin ihtilaf risâlesi', 'Kudret ile tekvin arasındaki farkı düşün.',
   'Mâtürîdîlere göre tekvin, kudretten ayrı, ezelî ve hakiki bir sıfattır; yaratılanlar ise hâdistir. Eş‘arîlere göre yaratma, kudret sıfatının varlıklarla ilişkisinden ibarettir ve ayrı bir sıfat değildir. Nesefî Akaidi tekvini ezelî sıfatlar arasında sayar, Teftâzânî iki görüşü tartışır.'),
 A('Ru’yetullah', 'Mü’minler ahirette Allah’ı görecek midir?', 'Kıyâme 75/22–23; En‘âm 6/103; Şerhu’l-Akāid; Kādî Abdülcebbâr, Şerhu’l-Usûli’l-hamse', 'Mu‘tezile “Gözler onu idrak edemez” âyetine dayanır.',
   'Ehl-i sünnete göre ru’yet aklen mümkün ve naklen sabittir: Kıyâme 22–23 ve “Ayı gördüğünüz gibi Rabbinizi göreceksiniz” hadisi. Mu‘tezile, görmenin cisimlik ve yön gerektirdiğini söyleyerek reddeder ve En‘âm 103’e dayanır. Ehl-i sünnet o âyetteki “idrak”i kuşatma olarak yorumlar: görmek kuşatmak değildir.'),
 A('Kesb ve cüz’î irade', 'İnsanın fiilleri konusunda Eş‘arî’nin “kesb” anlayışı ile Mâtürîdî’nin anlayışı arasında fark var mıdır?', 'Kitâbü’t-Tevhîd; el-Luma‘; Şerhu’l-Akāid; Nazmü’l-ferâid', 'Kulun kudretinin fiilde bir etkisi olup olmadığına bak.',
   'Her iki ekole göre fiilleri yaratan Allah’tır, kul ise fiili kazanır (kesb). Eş‘arîlere göre kulun kudreti fiile eşlik eder ama onda etkili değildir. Mâtürîdîlere göre kulun seçimi (cüz’î irade) fiilin yönelişinde gerçek bir paya sahiptir; sorumluluğun dayanağı budur. Bu yüzden Mâtürîdîlik cebre daha uzak kabul edilir.'),
 A('Peygamber gelmeden sorumluluk', 'Kendisine peygamber daveti ulaşmamış biri Allah’ı tanımakla sorumlu mudur?', 'Kitâbü’t-Tevhîd; Tebsıratü’l-edille; Beyâzîzâde, İşârâtü’l-merâm; İsrâ 17/15', 'Hüsün-kubuh meselesiyle bağlantısını kur.',
   'Semerkant Mâtürîdîlerine ve Ebû Hanîfe’den gelen görüşe göre akıl Allah’ın varlığını bilmeyi gerektirir; düşünme süresi verilmiş akıllı kimse peygamber gelmese de sorumludur. Eş‘arîlere göre sorumluluk ancak şeriatla doğar (İsrâ 15: “Peygamber göndermedikçe azap etmeyiz”). Buhara Mâtürîdîleri bu konuda Eş‘arîlere yakın görüş bildirmiştir.')]

