ALISTIRMA['belagat'] = [
 A('“Zeyd arslandır”', '“Zeydün esedün” cümlesi teşbih midir, istiare midir?', 'Telhîs ve Muhtasarü’l-Meânî (teşbih ve istiare bahisleri)', 'İstiarede benzetilenlerden biri söylenmez.',
   'Benzetilen (Zeyd) söylendiği için çoğunluğa göre istiare değil, edat ve benzetme yönü atılmış “teşbîh-i belîğ”dir. İstiare olsaydı Zeyd zikredilmez, “bir arslan gördüm” gibi yalnız benzeyene yer verilirdi.'),
 A('“İyyâke na‘büdü”', 'Fâtiha 1/5’te mef‘ûlün (iyyâke) fiilden önce gelmesinin belâgattaki anlamı nedir?', 'Keşşâf; Beyzâvî; Telhîs (kasr ve takdim bahisleri)', 'Takdimin en meşhur faydasını düşün.',
   'Mef‘ûlün öne alınması kasr (tahsis) ifade eder: “Yalnız sana kulluk ederiz.” Ayrıca Allah’ın adını öne almak tazim içindir. Gaib hitaptan (el-hamdü lillâh) muhataba (iyyâke) geçiş de iltifât sanatıdır.'),
 A('Bakara 14–15’te fasıl', '“Ve izâ halev ilâ şeyâtînihim kâlû innâ meakum…” âyetinden sonra gelen “Allâhu yestehziu bihim” cümlesi neden “ve” ile bağlanmamıştır?', 'Telhîs ve Muhtasar (fasl ve vasl); Keşşâf', 'Bağlansaydı hangi cümleye bağlanmış gibi anlaşılırdı?',
   '“Ve” ile bağlansaydı ya münafıkların sözüne (“dediler”) atfedilmiş olurdu ki bu, sözün onlara ait olduğu yanlış anlamını verirdi; ya da “dediler” cümlesine bağlanırdı ki Allah’ın onlarla alay etmesi “yalnız kaldıklarında” kaydına bağlanmış olurdu. Bu yanlış anlamları önlemek için fasıl yapılmıştır.'),
 A('Hûd 44 ve i‘câz', '“Ve kîle yâ ardu’bleî mâeki ve yâ semâü akliî…” âyetinde belâgatçıların saydığı incelikler nelerdir?', 'Sekkâkî, Miftâhu’l-ulûm; Keşşâf; Suyûtî, el-İtkân (i‘câz)', 'Yere ve göğe akıllı varlıklar gibi hitap edilmesinden başla.',
   'Yere ve göğe nida ile hitap edilmesi (teşhis ve istiare), “bel‘” (yutma) fiilinin suya kullanılması, emirlerin failinin söylenmeden “kîle” denmesi (azamet), kısa cümlelerle olayın bütün aşamalarının anlatılması (îcâz) ve kelimelerin uyumu sayılır. Sekkâkî bu âyeti belâgatın bütün yönlerinden inceler.'),
 A('Kinaye', '“Kılıç kını uzun, külü çok” (tavîlü’n-necâd, kesîru’r-ramâd) ifadeleri neyi anlatır?', 'Telhîs ve Muhtasar (kinaye bahsi)', 'Kinayede hakiki anlam da kastedilebilir.',
   '“Kılıç kınının uzun olması” boyunun uzunluğundan, “külünün çok olması” çok yemek pişirmesinden, yani misafirperverliğinden kinayedir. Kinayede gerçek anlamın kastedilmesi de mümkündür; mecazdan farkı budur.'),
 A('“Yâ”nın hazfi', 'Kur’an’daki dualarda (ör. “Rabbenâ”) nida harfinin söylenmemesinin anlamı nedir?', 'Keşşâf; Telhîs (hazf); Beyzâvî, Meryem 19/4', 'Nida edatları uzak ve yakın için farklıdır.',
   'Kur’an’daki dualarda nida harfi çoğunlukla düşürülür. Belâgatçılar bunu Allah’ın kuluna yakınlığının ve kulun acele ile yakarışının ifadesi olarak açıklar; uzağa seslenmek için kullanılan “yâ”nın atılması yakınlık hissi verir.')]
